veltStylesContent:
/* Place Velt UI customization styles here */

/* Theme Configuration - Based on Figma Design */
:root {
  /* Typography */
  --velt-default-font-family: Poppins;

  /* Border Radius */
  --velt-border-radius-2xs: 0.061rem; /* 0.972px */
  --velt-border-radius-xs: 0.125rem; /* 2px */
  --velt-border-radius-sm: 0.375rem; /* 6px */
  --velt-border-radius-md: 0.750rem; /* 12px */
